from fastapi import FastAPI
from fastapi.responses import HTMLResponse,JSONResponse,Response
import math
app=FastAPI()
@app.get('/manifest.json')
def m():return JSONResponse({'name':'Dieng'})
@app.get('/sw.js')
def s():return Response('a',media_type='application/javascript')
def ps(l,k):
 return(l**k*math.exp(-l))/math.factorial(k)
@app.get('/',response_class=HTMLResponse)
def home():
 h="<html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'>"
 h+="<style>body{margin:0;background:#06120e;color:#fff;font-family:system-ui;padding:6px}h1{color:#00ff88;font-size:11px;text-align:center}.card{background:#10261e;padding:8px;margin:6px 0;border-radius:12px;border:1px solid #ffffff12;font-size:11px}.top{background:#10261e;border:1px solid #00ff8840;border-radius:12px;padding:8px;margin:6px}.inputs{display:flex;gap:4px}.inputs input{flex:1;background:#0f2a1e;border:1px solid #00ff8830;border-radius:7px;padding:8px;color:#fff;text-align:center;font-weight:700}.small{display:flex;gap:4px;margin-top:4px}.small input{flex:1;background:#0a1f18;border:1px solid #00ff8820;border-radius:6px;padding:6px;color:#9effd0;text-align:center;font-size:10px}.vs{background:#0a2e22;color:#00ff88;font-weight:900;border-radius:999px;padding:4px 7px}.btn{width:100%;background:#00ff88;color:#06120e;border:0;border-radius:7px;padding:9px;font-weight:900;cursor:pointer;margin-top:4px}.v1n2{background:linear-gradient(90deg,#00ff88,#00aaff);color:#000;padding:8px;border-radius:8px;text-align:center;font-weight:900}.sc{background:#123829;border:2px solid #00ff88;border-radius:10px;padding:8px;text-align:center;margin:6px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:4px;margin-top:4px}.box{background:#0a2e22;border:1px solid #00ff8820;border-radius:7px;padding:6px;text-align:center;font-size:10px}.box.c{border-color:#00ff88;background:#123829;font-weight:900}label{font-size:9px;color:#00ff88}</style></head><body>"
 h+="<h1>Dieng ETAPE 1 - FOOT PRO VIP</h1><div class=top><div class=inputs><input id=fa value='AEK'><div class=vs>VS</div><input id=fb value='Real'></div>"
 h+="<div class=small><div style=flex:1><label>AEK Marques 5m</label><input id=fam type=number value=7></div><div style=flex:1><label>AEK Encaisses 5m</label><input id=fac type=number value=4></div></div>"
 h+="<div class=small><div style=flex:1><label>Real Marques 5m</label><input id=fbm type=number value=6></div><div style=flex:1><label>Real Encaisses 5m</label><input id=fbc type=number value=5></div></div>"
 h+="<button class=btn onclick='gf()'>ANALYSER FOOT PRO DISCIPLINE</button></div><div class=card id=rf>Entre les vrais chiffres Flashscore</div>"
 h+="<script>function fc(n){if(n<=1)return 1;var r=1;for(var i=2;i<=n;i++){r*=i}return r}function ps(l,k){return Math.pow(l,k)*Math.exp(-l)/fc(k)}"
 h+="function gf(){var am=parseFloat(fam.value),ac=parseFloat(fac.value),bm=parseFloat(fbm.value),bc=parseFloat(fbc.value);if(isNaN(am)){document.getElementById('rf').innerHTML='<span style=color:#ff4444>Entre les 4 chiffres</span>';return}var atkA=am/5,defA=ac/5,atkB=bm/5,defB=bc/5;var xgA=Math.min(2.8,Math.max(0.4,atkA*0.7+defB*0.3)),xgB=Math.min(2.8,Math.max(0.4,atkB*0.7+defA*0.3)),tot=xgA+xgB;var sc=[];for(var i=0;i<=5;i++){for(var j=0;j<=5;j++){sc.push({s:i+'-'+j,p:ps(xgA,i)*ps(xgB,j)*100})}}sc.sort(function(a,b){return b.p-a.p});var s1=sc[0],s2=sc[1];var pt=[];for(var k=0;k<=8;k++){pt[k]=ps(tot,k)}var sum=0;for(var k=0;k<pt.length;k++){sum+=pt[k]}var tp=[];for(var k=0;k<pt.length;k++){tp[k]=pt[k]/sum*100}var by=0;for(var i=1;i<=5;i++){for(var j=1;j<=5;j++){by+=ps(xgA,i)*ps(xgB,j)*100}}var m=[];m.push({n:'1 But',p:tp[1]});m.push({n:'2 Buts',p:tp[2]});m.push({n:'1-2',p:tp[1]+tp[2]});m.push({n:'Over 2.5',p:tp[3]+tp[4]+tp[5]+tp[6]+tp[7]});m.push({n:'BTTS Oui',p:by});m.sort(function(a,b){return b.p-a.p});var gr='';for(var i=0;i<m.length;i++){var r=m[i];var cl=r.n==m[0].n?' c':'';gr+='<div class=\"box'+cl+'\"><b>'+r.n+'</b><br>'+r.p.toFixed(1)+'%</div>'}var hh='';hh+='<div class=v1n2>V1 '+(50+(atkA-defA)*8).toFixed(1)+'% - V2 '+(50+(atkB-defB)*8).toFixed(1)+'%</div><div style=font-size:10px;background:#0f2a1e;padding:5px;border-radius:6px>FORME REELLE 5M: '+fa.value+' '+am+'M/'+ac+'E | '+fb.value+' '+bm+'M/'+bc+'E<br>xG PRO DISCIPLINE '+xgA.toFixed(2)+'+'+xgB.toFixed(2)+'='+tot.toFixed(2)+' (plafonne 0.4-2.8)</div><div class=sc><b>SCORES EXACTS PRO</b><br><b>'+s1.s+' '+s1.p.toFixed(1)+'%</b> - <b>'+s2.s+' '+s2.p.toFixed(1)+'%</b></div><div class=grid>'+gr+'</div><div style=font-size:9px;color:#00ff88;margin-top:4px>ZERO INVENTION - Base uniquement sur tes 4 chiffres</div>';document.getElementById('rf').innerHTML=hh}</script></body></html>"
 return HTMLResponse(h)
